function parseAiJson(val) {
    if (!val) return {};
    if (typeof val === 'object') return val;
    let s = String(val).trim();
    s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/g, '').trim();
    try {
        return JSON.parse(s);
    } catch (e) {
        let match = s.match(/(\{[\s\S]*\})/);
        if (match) {
            try { return JSON.parse(match[1]); } catch (e2) {}
        }
    }
    return {};
}

