        }
    };
    if (item.binary) newItem.binary = item.binary;
    outItems.push(newItem);
}
return outItems;

if (tags_str) {
    let tagArr = tags_str.split(',');
    let safeTags = [];
    let curLen = 0;
    for (let t of tagArr) {
        let tClean = t.trim();
        if (!tClean) continue;
        let tLen = tClean.length + (tClean.includes(' ') ? 2 : 0) + (safeTags.length ? 1 : 0);
        if (curLen + tLen > 380) break;
        safeTags.push(tClean);
        curLen += tLen;
    }
    tags_str = safeTags.join(',');
}

let stdoutStr = $json.stdout || '';
let data = {};
try {
