    } catch(e3) {
        shortTitle = 'A vs B en 60 segundos ⚡ #Shorts';
    }
}

const items = $input.all();
const outItems = [];
for (let item of items) {
    let newItem = {
        json: {
            ...item.json,
            title: shortTitle,
            description: desc,
            tags_str: meta.tags_str || 'Shorts,comparativa,amazon,vs',
            pinned_comment: meta.pinned_comment || ''
        }
    };
    if (item.binary) newItem.binary = item.binary;
    outItems.push(newItem);
}
return outItems;

