let scraperJson = $('1b. Parsear Scraper').first().json || {};
let tematicaJson = $('0b. Parsear Temática').first().json || {};
let configJson = $('Configuración Parámetros').first().json || {};

let p_dir = scraperJson.project_dir || tematicaJson.project_dir || '';
let niche = configJson.channel_niche || '';
let query = tematicaJson.search_query || scraperJson.query || '';

let productA = scraperJson.product_a || {};
let productB = scraperJson.product_b || {};
let brandA = productA.brand || 'Marca A';
let brandB = productB.brand || 'Marca B';
let titleA = productA.title || 'Producto A';
let titleB = productB.title || 'Producto B';
let priceA = productA.price || 'Oferta';
let priceB = productB.price || 'Oferta';
let ratingA = productA.rating || '4.5';
let ratingB = productB.rating || '4.5';

let promptTextShort = `Nicho del canal: ${niche}
Temática: ${query}
Formato: COMPARATIVA A vs B

PRODUCTO A: ${titleA} (${brandA})
Precio: ${priceA} | Rating: ${ratingA}

PRODUCTO B: ${titleB} (${brandB})
Precio: ${priceB} | Rating: ${ratingB}

Genera un guion corto de impacto (~110 palabras, <50 segundos) para un YouTube Short comparativo.
Estructura:
1. Hook impactante: pregunta directa "¿${brandA} o ${brandB}?"
2. Dato clave de cada producto (1 frase por producto)
3. Diferencia principal entre ambos
4. CTA: "¿Cuál elegirías TÚ? Comenta A o B"`;

return [{
    json: {
        project_dir: p_dir,
        promptTextShort: promptTextShort,
        format: 'vs',
        product_a: productA,
        product_b: productB
    }
}];

